    'trapped_ion_and_qc': ['trapped ion', 'ion trap', 'quantum computing', 'quantum computer', 'qubit', 'quantum gate', 'quantum algorithm', 'quantum entanglement', 'quantum state', 'quantum circuit', 'rydberg', 'laser cooling', 'quantum simulation', 'quantum information'],
    'black_hole': ['black hole', 'event horizon', 'hawking radiation', 'schwarzschild', 'kerr', 'singularity', 'accretion disk', 'gravitational collapse', 'general relativity', 'spacetime'],
    'DNA': ['dna', 'genome', 'genetic', 'gene', 'nucleotide', 'chromosome', 'mutation', 'protein', 'transcription', 'replication', 'sequence', 'genomic', 'genotype', 'allele', 'helix'],
